<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$notice='';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{pv_require_csrf();$to=trim((string)($_POST['to']??''));$subject=trim((string)($_POST['subject']??''));$body=trim((string)($_POST['body']??''));if($to===''||$subject===''||$body==='')throw new RuntimeException('Recipient, subject and message are required.');if(strlen($subject)>120||strlen($body)>5000)throw new RuntimeException('Message is too long.');$target=dn_member_by_username($db,$to);if(!$target)throw new RuntimeException('Tamer not found.');if((int)$target['id']===$uid)throw new RuntimeException('Send messages to another tamer.');if((int)$target['messonoff']===0)throw new RuntimeException('That tamer has private messages disabled.');$now=time();$stmt=$db->prepare('INSERT INTO messages(sender_id,recipient_id,subject,body,created_at) VALUES(?,?,?,?,?)');$rid=(int)$target['id'];$stmt->bind_param('iissi',$uid,$rid,$subject,$body,$now);if(!$stmt->execute())throw new RuntimeException($stmt->error);$stmt->close();if((int)$target['messnotifyonoff']!==0)dn_notify($db,$rid,'New message from '.(string)$_SESSION['myuser'],$subject,'messages.php','message');$notice='Message sent.';dn_world_event('game','message.sent','Sent a private message',['target_id'=>$rid]);}catch(Throwable $e){$error=$e->getMessage();}}
$read=max(0,(int)($_GET['read']??0));$selected=null;if($read>0){$stmt=$db->prepare('SELECT msg.*,s.username sender_name,r.username recipient_name FROM messages msg JOIN members s ON s.id=msg.sender_id JOIN members r ON r.id=msg.recipient_id WHERE msg.id=? AND (msg.sender_id=? OR msg.recipient_id=?) LIMIT 1');$stmt->bind_param('iii',$read,$uid,$uid);$stmt->execute();$selected=$stmt->get_result()->fetch_assoc();$stmt->close();if($selected&&(int)$selected['recipient_id']===$uid&&$selected['read_at']===null){$now=time();$stmt=$db->prepare('UPDATE messages SET read_at=? WHERE id=? AND recipient_id=?');$stmt->bind_param('iii',$now,$read,$uid);$stmt->execute();$stmt->close();}}
$rows=[];$stmt=$db->prepare('SELECT msg.*,s.username sender_name,r.username recipient_name FROM messages msg JOIN members s ON s.id=msg.sender_id JOIN members r ON r.id=msg.recipient_id WHERE (msg.recipient_id=? AND msg.recipient_deleted=0) OR (msg.sender_id=? AND msg.sender_deleted=0) ORDER BY msg.created_at DESC LIMIT 100');$stmt->bind_param('ii',$uid,$uid);$stmt->execute();$r=$stmt->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$stmt->close();$prefill=trim((string)($_GET['to']??''));pv_page_start('Messages','messages.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('messages.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">PRIVATE TAMER COMMS</span><h1>Messages</h1><p class="pv-subtle">Database-backed private messages between Digimon NXT accounts.</p></div></div><?php if($notice):?><div class="pv-flash success"><?=pv_h($notice)?></div><?php endif;?><?php if($error):?><div class="pv-flash error"><?=pv_h($error)?></div><?php endif;?><div class="pv-message-layout"><section class="pv-card pv-message-compose" style="padding:18px"><h2>Compose</h2><form method="post"><?=pv_csrf_field()?><div class="pv-field"><label>To</label><input name="to" maxlength="45" value="<?=pv_h($prefill)?>" required></div><div class="pv-field"><label>Subject</label><input name="subject" maxlength="120" required></div><div class="pv-field"><label>Message</label><textarea name="body" rows="7" maxlength="5000" required></textarea></div><button class="pv-button">Send Transmission</button></form></section><section class="pv-card pv-message-list" style="padding:18px"><h2>Inbox / Sent</h2><?php foreach($rows as $msg):$incoming=(int)$msg['recipient_id']===$uid;?><a class="pv-message-row <?=($incoming&&$msg['read_at']===null)?'unread':''?>" href="<?=pv_h(pv_url('messages.php?read='.(int)$msg['id']))?>"><strong><?=pv_h($incoming?(string)$msg['sender_name']:'To: '.(string)$msg['recipient_name'])?></strong><span><?=pv_h((string)$msg['subject'])?></span><small><?=date('Y-m-d H:i',(int)$msg['created_at'])?></small></a><?php endforeach;?><?php if(!$rows):?><div class="pv-empty">No transmissions yet.</div><?php endif;?></section></div><?php if($selected):?><section class="pv-card pv-message-reader" style="padding:20px;margin-top:14px"><small><?=pv_h((string)$selected['sender_name'])?> → <?=pv_h((string)$selected['recipient_name'])?> · <?=date('Y-m-d H:i',(int)$selected['created_at'])?></small><h2><?=pv_h((string)$selected['subject'])?></h2><div class="pv-message-body"><?=nl2br(pv_h((string)$selected['body']))?></div></section><?php endif;?></section></main></div><?php pv_page_end(); ?>
